17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.util.Collection;
20	import java.util.List;
21	
22	import org.springframework.http.HttpHeaders;
23	import org.springframework.http.HttpStatus;
24	import org.springframework.http.ResponseEntity;
25	import org.springframework.samples.petclinic.mapper.OwnerMapper;
26	import org.springframework.samples.petclinic.mapper.PetMapper;
27	import org.springframework.samples.petclinic.mapper.VisitMapper;
28	import org.springframework.samples.petclinic.model.Owner;
29	import org.springframework.samples.petclinic.model.Pet;
30	import org.springframework.samples.petclinic.model.Visit;
31	import org.springframework.samples.petclinic.rest.advice.CityAtCapacityException;
32	import org.springframework.samples.petclinic.rest.advice.DailyOwnerLimitException;
33	import org.springframework.samples.petclinic.rest.advice.DuplicateHouseholdException;
34	import org.springframework.samples.petclinic.rest.advice.DuplicateTelephoneException;
35	import org.springframework.samples.petclinic.rest.advice.InvalidAddressException;
36	import org.springframework.samples.petclinic.rest.advice.InvalidEmailException;
37	import org.springframework.samples.petclinic.rest.advice.InvalidTelephoneException;
38	import org.springframework.samples.petclinic.rest.api.OwnersApi;
39	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
40	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
41	import org.springframework.samples.petclinic.rest.dto.PetDto;
42	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
43	import org.springframework.samples.petclinic.rest.dto.VisitDto;
44	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
45	import org.springframework.samples.petclinic.service.ClinicService;
46	import org.springframework.samples.petclinic.util.Households;
47	import org.springframework.security.access.prepost.PreAuthorize;
48	import org.springframework.web.bind.annotation.CrossOrigin;
49	import org.springframework.web.bind.annotation.RequestMapping;
50	import org.springframework.web.bind.annotation.RestController;
51	import org.springframework.web.util.UriComponentsBuilder;
52	
53	import jakarta.transaction.Transactional;
54	
55	/**
56	 * @author Vitaliy Fedoriv
57	 */
58	
59	@RestController
60	@CrossOrigin(exposedHeaders = "errors, content-type")
61	@RequestMapping("/api")
62	public class OwnerRestControllerV1 implements OwnersApi {
63	
64	    private final ClinicService clinicService;
65	
66	    private final OwnerMapper ownerMapper;
67	
68	    private final PetMapper petMapper;
69	
70	    private final VisitMapper visitMapper;
71	
72	    public OwnerRestControllerV1(ClinicService clinicService,
73	                                 OwnerMapper ownerMapper,
74	                                 PetMapper petMapper,
75	                                 VisitMapper visitMapper) {
76	        this.clinicService = clinicService;
77	        this.ownerMapper = ownerMapper;
78	        this.petMapper = petMapper;
79	        this.visitMapper = visitMapper;
80	    }
81	
82	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
83	    @Override
84	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
85	        Collection<Owner> owners;
86	        if (lastName != null) {
87	            owners = this.clinicService.findOwnerByLastName(lastName);
88	        } else {
89	            owners = this.clinicService.findAllOwners();
90	        }
91	        if (owners.isEmpty()) {
92	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
93	        }
94	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
95	    }
96	
97	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
98	    @Override
99	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
100	        Owner owner = this.clinicService.findOwnerById(ownerId);
101	        if (owner == null) {
102	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
103	        }
104	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
105	    }
106	
107	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
108	    @Override
109	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
110	        HttpHeaders headers = new HttpHeaders();
111	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
112	        owner.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
113	        rejectDailyLimitReached();
114	        rejectCityAtCapacity(owner.getCity());
115	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
116	            rejectDuplicateHousehold(owner.getLastName(), owner.getAddress());
117	        }
118	        String telephone = normalizeTelephone(ownerFieldsDto.getTelephone());
119	        rejectDuplicateTelephone(telephone);
120	        owner.setTelephone(telephone);
121	        owner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
122	        if (owner.getRegistrationDate() == null) {
123	            owner.setRegistrationDate(java.time.LocalDate.now());
124	        }
125	        owner.setCustomerCode(assignCustomerCode(owner.getCity(), owner.getLastName()));
126	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
127	        this.clinicService.saveOwner(owner);
128	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
129	        headers.setLocation(UriComponentsBuilder.newInstance()
130	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
131	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
132	    }
133	
134	    /**
135	     * The maximum number of owners that may be created in a single day. Creating an owner once this
136	     * many owners already carry today's {@code registrationDate} is rejected.
137	     */
138	    private static final int DAILY_OWNER_LIMIT = 100;
139	
140	    /**
141	     * Rejects creating an owner once {@value #DAILY_OWNER_LIMIT} or more owners have already been
142	     * created today, counted by {@code registrationDate} equal to the current date. Owners with no
143	     * {@code registrationDate} are ignored.
144	     *
145	     * @throws DailyOwnerLimitException (429 Too Many Requests) if the daily limit is already reached
146	     */
147	    private void rejectDailyLimitReached() {
148	        java.time.LocalDate today = java.time.LocalDate.now();
149	        long count = this.clinicService.findAllOwners().stream()
150	            .filter(existing -> today.equals(existing.getRegistrationDate()))
151	            .count();
152	        if (count >= DAILY_OWNER_LIMIT) {
153	            throw new DailyOwnerLimitException(today);
154	        }
155	    }
156	
157	    /**
158	     * The maximum number of owners a single city may contain. Creating an owner in a city that
159	     * already holds this many owners is rejected.
160	     */
161	    private static final int CITY_CAPACITY = 50;
162	
163	    /**
164	     * Rejects creating an owner whose city already contains {@value #CITY_CAPACITY} or more owners.
165	     * Owners are counted per city comparing the city name case-insensitively (a {@code null} city is
166	     * treated as empty), the same way {@link #assignCustomerCode} counts a city's owners.
167	     *
168	     * @param city the city of the owner being created
169	     * @throws CityAtCapacityException (409 Conflict) if the city is already at capacity
170	     */
171	    private void rejectCityAtCapacity(String city) {
172	        String cityValue = city == null ? "" : city;
173	        long count = this.clinicService.findAllOwners().stream()
174	            .filter(existing -> cityValue.equalsIgnoreCase(
175	                existing.getCity() == null ? "" : existing.getCity()))
176	            .count();
177	        if (count >= CITY_CAPACITY) {
178	            throw new CityAtCapacityException(city);
179	        }
180	    }
181	
182	    /**
183	     * Assigns an owner's {@code customerCode} on create, formatted {@code '<CITY3>-<LAST3>-<NNNN>'}
184	     * where CITY3 is the upper-cased first three letters of the city, LAST3 the upper-cased first
185	     * three letters of the last name and NNNN a per-city 4-digit zero-padded sequence equal to one
186	     * more than the number of owners already in that city (e.g. {@code 'SYD-SMI-0007'}).
187	     *
188	     * @param city the owner's city
189	     * @param lastName the owner's last name
190	     * @return the assigned customer code
191	     */
192	    private String assignCustomerCode(String city, String lastName) {
193	        String city3 = prefix3(city);
194	        String last3 = prefix3(lastName);
195	        String cityValue = city == null ? "" : city;
196	        int sequence = (int) this.clinicService.findAllOwners().stream()
197	            .filter(existing -> cityValue.equalsIgnoreCase(
198	                existing.getCity() == null ? "" : existing.getCity()))
199	            .count() + 1;
200	        return String.format("%s-%s-%04d", city3, last3, sequence);
201	    }
202	
203	    /**
204	     * Returns the upper-cased first three letters of the given value, or fewer if the value is
205	     * shorter, treating {@code null} as empty.
206	     */
207	    private String prefix3(String value) {
208	        String name = value == null ? "" : value;
209	        return name.substring(0, Math.min(3, name.length()))
210	            .toUpperCase(java.util.Locale.ROOT);
211	    }
212	
213	    /**
214	     * Counts how many existing owners share the given first and last name, compared
215	     * case-insensitively, at the time this owner is created. The value excludes the owner
216	     * being created (which has not yet been saved) and is stored on the new owner and returned
217	     * as its {@code namesakeCount}.
218	     *
219	     * @param firstName the first name of the owner being created
220	     * @param lastName the last name of the owner being created
221	     * @return the number of existing owners with the same first and last name
222	     */
223	    private int countNamesakes(String firstName, String lastName) {
224	        String first = firstName == null ? "" : firstName;
225	        String last = lastName == null ? "" : lastName;
226	        return (int) this.clinicService.findAllOwners().stream()
227	            .filter(existing -> first.equalsIgnoreCase(existing.getFirstName())
228	                && last.equalsIgnoreCase(existing.getLastName()))
229	            .count();
230	    }
231	
232	    /**
233	     * Normalizes an owner's telephone on create into E.164 form. Spaces, dashes and brackets are
234	     * stripped. A leading '+' and its country code are kept as given; otherwise country code '+61' is
235	     * assumed and a single leading '0' is dropped from the national digits. The resulting number must
236	     * have 8 to 15 digits after the '+'. For example {@code "0412 345 678"} becomes
237	     * {@code "+61412345678"}. The E.164 value is stored and returned.
238	     *
239	     * @param telephone the raw telephone as submitted
240	     * @return the normalized E.164 telephone (a '+' followed by 8 to 15 digits)
241	     * @throws InvalidTelephoneException (400 Bad Request) if the value cannot form a valid E.164 number
242	     */
243	    private String normalizeTelephone(String telephone) {
244	        String raw = telephone == null ? "" : telephone.trim();
245	        boolean hasCountryCode = raw.startsWith("+");
246	        String cleaned = raw.replaceAll("[\\s()\\-]", "");
247	        if (hasCountryCode) {
248	            cleaned = cleaned.substring(1);
249	        }
250	        String digits;
251	        if (hasCountryCode) {
252	            digits = cleaned;
253	        } else {
254	            if (cleaned.startsWith("0")) {
255	                cleaned = cleaned.substring(1);
256	            }
257	            digits = "61" + cleaned;
258	        }
259	        if (!digits.matches("[0-9]{8,15}")) {
260	            throw new InvalidTelephoneException(telephone);
261	        }
262	        return "+" + digits;
263	    }
264	
265	    /**
266	     * Syntactic email pattern: a non-empty local part, an '@', a domain with at least one dot and a
267	     * multi-character top-level label. Deliberately lenient about the exact character set while still
268	     * rejecting values that are clearly not addresses (e.g. missing '@').
269	     */
270	    private static final java.util.regex.Pattern EMAIL_PATTERN =
271	        java.util.regex.Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]{2,}$");
272	
273	    /**
274	     * Normalizes an owner's email. Email is optional: a {@code null} or blank value is left as
275	     * {@code null} (no email). When present it must be a syntactically valid address; the value is
276	     * lower-cased before being stored and returned.
277	     *
278	     * @param email the raw email as submitted, may be {@code null}
279	     * @return the lower-cased email, or {@code null} when none was supplied
280	     * @throws InvalidEmailException (400 Bad Request) if a non-blank value is not a valid address
281	     */
282	    private String normalizeEmail(String email) {
283	        if (email == null || email.isBlank()) {
284	            return null;
285	        }
286	        String trimmed = email.trim();
287	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
288	            throw new InvalidEmailException(email);
289	        }
290	        return trimmed.toLowerCase(java.util.Locale.ROOT);
291	    }
292	
293	    /**
294	     * Common street-type abbreviations expanded to their full word during address normalization.
295	     */
296	    private static final java.util.Map<String, String> ADDRESS_ABBREVIATIONS = java.util.Map.of(
297	        "ST", "STREET",
298	        "RD", "ROAD",
299	        "AVE", "AVENUE");
300	
301	    /**
302	     * Normalizes an owner's address on create. Surrounding whitespace is trimmed and internal runs of
303	     * whitespace collapse to a single space, the value is upper-cased and common street-type
304	     * abbreviations are expanded to their full word ({@code ST} to {@code STREET}, {@code RD} to
305	     * {@code ROAD}, {@code AVE} to {@code AVENUE}). For example {@code "  12  main  st "} becomes
306	     * {@code "12 MAIN STREET"}. The normalized value is stored and returned, and is also the form used
307	     * for every address comparison (household duplicate detection and the shared household id).
308	     *
309	     * @param address the raw address as submitted
310	     * @return the normalized address
311	     * @throws InvalidAddressException (400 Bad Request) if the address is blank after normalization
312	     */
313	    private String normalizeAddress(String address) {
314	        String collapsed = (address == null ? "" : address).trim().replaceAll("\\s+", " ");
315	        if (collapsed.isEmpty()) {
316	            throw new InvalidAddressException(address);
317	        }
318	        String[] tokens = collapsed.toUpperCase(java.util.Locale.ROOT).split(" ");
319	        StringBuilder normalized = new StringBuilder(collapsed.length());
320	        for (int i = 0; i < tokens.length; i++) {
321	            if (i > 0) {
322	                normalized.append(' ');
323	            }
324	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
325	        }
326	        return normalized.toString();
327	    }
328	
329	    /**
330	     * Rejects creating an owner whose E.164 telephone is already used by another owner. Telephones of
331	     * existing owners are normalized to E.164 the same way before comparison, so equivalent numbers
332	     * submitted in different formats (e.g. national {@code "0412 345 678"} and international
333	     * {@code "+61 412 345 678"}) are still treated as duplicates.
334	     *
335	     * @param telephone the E.164 telephone of the owner being created
336	     * @throws DuplicateTelephoneException (409 Conflict) if another owner already uses this telephone
337	     */
338	    private void rejectDuplicateTelephone(String telephone) {
339	        boolean duplicate = this.clinicService.findAllOwners().stream()
340	            .map(Owner::getTelephone)
341	            .filter(existing -> existing != null)
342	            .map(this::toE164OrNull)
343	            .filter(existing -> existing != null)
344	            .anyMatch(telephone::equals);
345	        if (duplicate) {
346	            throw new DuplicateTelephoneException(telephone);
347	        }
348	    }
349	
350	    /**
351	     * Normalizes an existing owner's telephone to E.164 for duplicate comparison, returning
352	     * {@code null} instead of throwing when the stored value cannot form a valid E.164 number.
353	     */
354	    private String toE164OrNull(String telephone) {
355	        try {
356	            return normalizeTelephone(telephone);
357	        } catch (InvalidTelephoneException e) {
358	            return null;
359	        }
360	    }
361	
362	    /**
363	     * Rejects creating an owner who shares a household with an existing owner, i.e. another owner
364	     * already has the same last name and the same address. Last names are compared case-insensitively
365	     * with whitespace collapsed; addresses are compared in their normalized form (see
366	     * {@link #normalizeAddress}, which every owner's stored address already uses), so values that
367	     * differ only in letter case, spacing or a common street-type abbreviation still count as a match.
368	     * This check is skipped when the request sets {@code sharesHousehold} to {@code true}.
369	     *
370	     * @param lastName the last name of the owner being created
371	     * @param address the normalized address of the owner being created
372	     * @throws DuplicateHouseholdException (409 Conflict) if another owner shares this household
373	     */
374	    private void rejectDuplicateHousehold(String lastName, String address) {
375	        String normalizedLastName = Households.normalize(lastName);
376	        String normalizedAddress = Households.normalize(address);
377	        boolean duplicate = this.clinicService.findAllOwners().stream()
378	            .anyMatch(existing ->
379	                Households.normalize(existing.getLastName()).equals(normalizedLastName)
380	                    && Households.normalize(existing.getAddress()).equals(normalizedAddress));
381	        if (duplicate) {
382	            throw new DuplicateHouseholdException(lastName, address);
383	        }
384	    }
385	
386	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
387	    @Override
388	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
389	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
390	        if (currentOwner == null) {
391	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
392	        }
393	        currentOwner.setAddress(ownerFieldsDto.getAddress());
394	        currentOwner.setCity(ownerFieldsDto.getCity());
395	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
396	        currentOwner.setLastName(ownerFieldsDto.getLastName());
397	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
398	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
399	        this.clinicService.saveOwner(currentOwner);
400	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
401	    }
402	
403	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
404	    @Transactional
405	    @Override
406	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
407	        Owner owner = this.clinicService.findOwnerById(ownerId);
408	        if (owner == null) {
409	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
410	        }
411	        this.clinicService.deleteOwner(owner);
412	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
413	    }
414	
415	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
416	    @Override
417	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
418	        Owner owner = this.clinicService.findOwnerById(ownerId);
419	        if (owner == null) {
420	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
421	        }
422	        HttpHeaders headers = new HttpHeaders();
423	        Pet pet = petMapper.toPet(petFieldsDto);
424	        owner.setId(ownerId);
425	        pet.setOwner(owner);
426	        pet.getType().setName(null);
427	        this.clinicService.savePet(pet);
428	        PetDto petDto = petMapper.toPetDto(pet);
429	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
430	            .buildAndExpand(pet.getId()).toUri());
431	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
432	    }
433	
434	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
435	    @Override
436	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
437	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
438	        if (currentOwner != null) {
439	            Pet currentPet = this.clinicService.findPetById(petId);
440	            if (currentPet != null) {
441	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
442	                currentPet.setName(petFieldsDto.getName());
443	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
444	                this.clinicService.savePet(currentPet);
445	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
446	            }
447	        }
448	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
449	    }
450	
451	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
452	    @Override
453	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
454	        HttpHeaders headers = new HttpHeaders();
455	        Visit visit = visitMapper.toVisit(visitFieldsDto);
456	        Pet pet = new Pet();
457	        pet.setId(petId);
458	        visit.setPet(pet);
459	        this.clinicService.saveVisit(visit);
460	        VisitDto visitDto = visitMapper.toVisitDto(visit);
461	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
462	            .buildAndExpand(visit.getId()).toUri());
463	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
464	    }
465	
466	
467	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
468	    @Override
469	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
470	        Owner owner = this.clinicService.findOwnerById(ownerId);
471	        if (owner != null) {
472	            Pet pet = owner.getPet(petId);
473	            if (pet != null) {
474	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
475	            }
476	        }
477	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
478	    }
479	}
